function upload_document(array $c):array{$id=$_SERVER['HTTP_X_OPERATION_ID']??'';operation(['operationId'=>$id]);$kind=$_SERVER['HTTP_X_DOCUMENT_KIND']??'';$name=rawurldecode($_SERVER['HTTP_X_FILE_NAME']??'');$name=preg_replace('/[\r\n\/\\\\]/','_',$name);text($name,1,200);$special=in_array($kind,['submissionReceipt','officialResponse'],true);$allowed=array_column(field_set($c['route'],$c['data'])['documents'],'id');if($c['order'])$allowed[]='authority';if($special){require_admin();if($c['assignedTo']!==actor()||($kind==='submissionReceipt'?$c['state']!=='submitting':$c['state']!=='submitted'))fail('INVALID_STATE',409);}elseif(!in_array($kind,$allowed,true)||!in_array($c['state'],['draft','ordered','in_review','needs_information'],true))fail('DOCUMENT_NOT_EXPECTED');$old=record('document:'.$id,true);if($old){if($old['parent_id']!==$c['id'])fail('OPERATION_CONFLICT',409);return ['case'=>public_case($c)];}$bytes=file_get_contents('php://input',false,null,0,20000001);if(!$bytes||strlen($bytes)>20000000)fail('BODY_TOO_LARGE',413);$mime=(new finfo(FILEINFO_MIME_TYPE))->buffer($bytes);$extension=strtolower(pathinfo($name,PATHINFO_EXTENSION));if(!in_array($mime,['application/pdf','image/jpeg','image/png'],true)||($mime==='application/pdf'&&!str_starts_with($bytes,'%PDF-'))||!in_array($extension,['pdf','jpg','jpeg','png'],true)||($mime==='application/pdf'&&$extension!=='pdf')||($mime==='image/png'&&$extension!=='png')||($mime==='image/jpeg'&&!in_array($extension,['jpg','jpeg'],true)))fail('UNSUPPORTED_DOCUMENT');$normal=array_filter($c['documents'],fn($d)=>!in_array($d['kind'],['submissionReceipt','officialResponse'],true));if(!$special&&(count($normal)>=5||array_sum(array_column($normal,'size'))+strlen($bytes)>20000000))fail('FILE_LIMIT_OR_CONFLICT',409);$key=secret_hash($c['id'].':'.$id).'.bin';$dir=private_root().'/data/uploads';if(!is_dir($dir)&&!@mkdir($dir,0700,true)&&!is_dir($dir))fail('DOCUMENT_STORE_UNAVAILABLE',503);$file=$dir.'/'.$key;if(file_exists($file))fail('OPERATION_CONFLICT',409);$handle=@fopen($file,'x');if(!$handle)fail('DOCUMENT_STORE_UNAVAILABLE',503);chmod($file,0600);if(fwrite($handle,$bytes)!==strlen($bytes)){fclose($handle);unlink($file);fail('DOCUMENT_STORE_UNAVAILABLE',503);}fclose($handle);$GLOBALS['uploads_rollback'][]=$file;$doc=['id'=>$id,'kind'=>$kind,'name'=>$name,'size'=>strlen($bytes),'mime'=>$mime,'status'=>'received','uploadedAt'=>now(),'objectKey'=>$key];$n=$c;$n['documents'][]=$doc;put('document:'.$id,'document',$doc,$c['id']);$n=save_case($c,$n,$id,admin()?actor():'customer','upload',['id'=>$id,'kind'=>$kind,'sha256'=>hash('sha256',$bytes)]);http_response_code(201);return ['case'=>public_case($n)];}
